using System;
using System.Collections.Generic;

namespace ZR.Model.Contracts.Billing.Dto
{
    /// <summary>
    /// Billing Period DTO - فترة الفوترة
    /// Represents a single billing period generated by the BillingPeriodGenerator
    /// </summary>
    public class BillingPeriodDto
    {
        /// <summary>
        /// Period sequence number (1, 2, 3...)
        /// </summary>
        public int PeriodNumber { get; set; }

        /// <summary>
        /// Start date of the billing period
        /// </summary>
        public DateTime PeriodStart { get; set; }

        /// <summary>
        /// End date of the billing period
        /// </summary>
        public DateTime PeriodEnd { get; set; }

        /// <summary>
        /// Invoice generation date (when to create invoice)
        /// </summary>
        public DateTime DueDate { get; set; }

        /// <summary>
        /// Payment due date (DueDate + PaymentTermsDays)
        /// </summary>
        public DateTime PaymentDueDate { get; set; }

        /// <summary>
        /// Whether this is a pro-rated period
        /// </summary>
        public bool IsProRated { get; set; }

        /// <summary>
        /// Actual days in this period (for pro-rating)
        /// </summary>
        public int ActualDays { get; set; }

        /// <summary>
        /// Full period days (standard period length)
        /// </summary>
        public int FullPeriodDays { get; set; }

        /// <summary>
        /// Pro-rata factor (ActualDays / FullPeriodDays)
        /// </summary>
        public decimal ProRataFactor { get; set; }

        /// <summary>
        /// Period type: First, Middle, Last, Single
        /// </summary>
        public BillingPeriodType PeriodType { get; set; }

        /// <summary>
        /// Description for display (e.g., "January 2025")
        /// </summary>
        public string Description { get; set; }

        /// <summary>
        /// Arabic description
        /// </summary>
        public string DescriptionAr { get; set; }
    }

    /// <summary>
    /// Billing Period Type Enum
    /// </summary>
    public enum BillingPeriodType
    {
        /// <summary>Single period contract (start to end)</summary>
        Single = 0,
        /// <summary>First period (may be pro-rated)</summary>
        First = 1,
        /// <summary>Middle period (full period)</summary>
        Middle = 2,
        /// <summary>Last period (may be pro-rated)</summary>
        Last = 3
    }

    /// <summary>
    /// Period Generation Request DTO
    /// </summary>
    public class PeriodGenerationRequestDto
    {
        public Guid ContractId { get; set; }
        public DateTime ContractStartDate { get; set; }
        public DateTime? ContractEndDate { get; set; }
        public Enums.BillingFrequency BillingFrequency { get; set; }
        public int BillingDay { get; set; } = 1;
        public bool ProrateFirstPeriod { get; set; } = true;
        public bool ProrateLastPeriod { get; set; } = true;
        public int PaymentTermsDays { get; set; } = 30;
        public DateTime? GenerateFromDate { get; set; }
        public DateTime? GenerateToDate { get; set; }
        public int? MaxPeriodsToGenerate { get; set; }
    }

    /// <summary>
    /// Period Generation Result DTO
    /// </summary>
    public class PeriodGenerationResultDto
    {
        public Guid ContractId { get; set; }
        public List<BillingPeriodDto> Periods { get; set; } = new();
        public int TotalPeriodsGenerated { get; set; }
        public DateTime? FirstPeriodStart { get; set; }
        public DateTime? LastPeriodEnd { get; set; }
        public bool HasProRatedFirst { get; set; }
        public bool HasProRatedLast { get; set; }
        public List<string> Warnings { get; set; } = new();
    }

    /// <summary>
    /// Pro-Rata Calculation Method
    /// </summary>
    public enum ProRataMethod
    {
        /// <summary>Actual days / Actual days in period</summary>
        ActualActual = 0,
        /// <summary>Actual days / 30 (standard month)</summary>
        Actual30 = 1,
        /// <summary>Actual days / 360 (standard year)</summary>
        Actual360 = 2,
        /// <summary>30/360 convention (banking standard)</summary>
        Days30_360 = 3,
        /// <summary>Calendar month based</summary>
        CalendarMonth = 4
    }

    /// <summary>
    /// Rounding Method for calculations
    /// </summary>
    public enum RoundingMethod
    {
        /// <summary>Round up (ceiling)</summary>
        RoundUp = 0,
        /// <summary>Round down (floor)</summary>
        RoundDown = 1,
        /// <summary>Round to nearest</summary>
        RoundNearest = 2,
        /// <summary>Banker's rounding (round half to even)</summary>
        Banker = 3
    }
}
